import React from "react";
import styled from "@emotion/styled";
import { css, Global } from "@emotion/react";

// Données (mettre le parcours)
const timelineData = [
  { date: "1914", datetime: "1914", title: "Oui ?", content: ["Non"] },
  { date: "2023", datetime: "2023", title: "Institution des chartreux", content: ["Italy declares war"] },
  { date: "2025", datetime: "2025", title: "CPE Lyon", content: ["Baguette"] },
];

/* === Styled Components === */
const TimelineList = styled.ol`
  display: grid;
  grid-template-columns: max-content 1fr;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 2rem;
`;

const TimelineItemLi = styled.li`
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  gap: 0 3rem;

  &:not(:last-of-type) article::before {
    content: '';
    position: absolute;
    left: calc(-1.5rem);
    top: 2rem;
    bottom: -2rem;
    width: 3px;
    background-color: #d1d5db;
  }
`;

const TimelineDateDiv = styled.div`
  grid-column: 1;
  text-align: right;
  color: #6b7280;
  font-size: 2rem;
  font-weight: 200;
  transform: translateY(-0.6rem);
`;

const TimelineArticle = styled.article`
  grid-column: 2;
  position: relative;

  &::after {
    content: '';
    position: absolute;
    left: calc(-1.5rem);
    top: 0.5rem;
    width: 1rem;
    height: 1rem;
    border-radius: 50%;
    background-color: #3b82f6;
  }
`;

const ContentHeader = styled.header`
  h3 { font-size: 1.25rem; font-weight: 600; color: #111827; margin: 0 0 0.5rem; }
`;

const ContentDiv = styled.div`
  p { margin: 0 0 0.75rem; &:last-child { margin-bottom: 0; } }
`;

/* === TimelineItem === */
function TimelineItem({ date, datetime, title, content }) {
  return (
    <TimelineItemLi>
      <TimelineDateDiv>{date}</TimelineDateDiv>
      <TimelineArticle>
        <ContentHeader><h3>{title}</h3></ContentHeader>
        <ContentDiv>
          {content.map((p,i) => <p key={i}>{p}</p>)}
        </ContentDiv>
      </TimelineArticle>
    </TimelineItemLi>
  );
}

/* === App === */
function App() {
  return (
    <>
      <Global styles={css`body { font-family: system-ui, sans-serif; background: #f0f2f5; padding: 2rem; }`} />
      <TimelineList>
        {timelineData.map((item,i) => <TimelineItem key={i} {...item} />)}
      </TimelineList>
    </>
  );
}

export default App;
